import { DateTime } from "luxon";
import { 
// clearDynamicRules,
createUC, createUrl, getConfig, getSchedule, getTrialDay, isStoreUrl, log, saveSync, setSessionRules, } from "..";
import { setSyncPaddleData } from "../paddle";
import { sync } from "../sync";
async function init(install) {
    try {
        chrome.declarativeNetRequest.setExtensionActionOptions({
            displayActionCountAsBadgeText: true,
        });
        const cookies = await chrome.cookies.getAll({
            domain: "adgone.org",
        });
        cookies.forEach(async (cookie) => {
            switch (cookie.name) {
                case "user_id":
                case "userID":
                    if (cookie.value !== "") {
                        sync.user_id = cookie.value;
                    }
                    break;
                case "uc":
                case "userClass":
                    if (cookie.value !== "") {
                        sync.uc = parseInt(cookie.value);
                        sync.trialDay = await getTrialDay(sync.uc);
                    }
                    break;
                case "source":
                    if (cookie.value !== "") {
                        sync.source = cookie.value;
                    }
                    break;
                case "subscriber":
                    if (cookie.value !== "") {
                        sync.hasPaid = cookie.value === "true" ? true : false;
                    }
                    break;
                case "key":
                    if (cookie.value !== "") {
                        sync.key = cookie.value;
                    }
                    break;
                case "AG_Subscriber":
                    if (cookie.value === "true") {
                        sync.hasPaid = true;
                    }
            }
        });
        sync.timers.popup_tutorial = DateTime.now().toMillis();
        if (sync.uc === 17000101) {
            sync.uc = createUC();
            sync.trialDay = 1;
        }
        if (install) {
            chrome.runtime.setUninstallURL(createUrl("uninstall", null, sync));
            chrome.tabs.query({}, (tabs) => {
                tabs.forEach(async (tab) => {
                    if (isStoreUrl(tab.url)) {
                        await chrome.tabs.remove(tab.id);
                    }
                });
            });
            if (!sync.hasPaid) {
                await chrome.tabs.create({
                    url: createUrl("thankyou", null, sync),
                    active: true,
                    selected: true,
                });
            }
            else {
                await chrome.tabs.create({
                    url: createUrl("activated", "auto", sync),
                    active: true,
                    selected: true,
                });
            }
        }
        else {
            try {
                const deprecatedData = (await chrome.storage.sync.get([
                    "installData",
                    "trialDay",
                    "tutorial",
                    "showBATutorial",
                    "showPinTutorial",
                    "reviewAsked",
                    "stats",
                    "paddleData",
                    "fullPageLastShown",
                    "notificationLastShown",
                    "allowAdsonSite",
                ]));
                let blockingTutorialSet = false;
                let popupTutorialSet = false;
                let reviewSet = false;
                // load mv2 ext data
                if (deprecatedData.trialDay && deprecatedData.trialDay > 0) {
                    sync.trialDay = deprecatedData.trialDay;
                }
                if (deprecatedData.installData) {
                    if (deprecatedData.installData.user_id &&
                        deprecatedData.installData.user_id !== sync.user_id) {
                        sync.user_id = deprecatedData.installData.user_id;
                    }
                    if (deprecatedData.installData.installDate) {
                        const installDate = parseInt(deprecatedData.installData.installDate);
                        if (installDate &&
                            installDate > 0 &&
                            installDate !== sync.uc) {
                            sync.uc = installDate;
                        }
                    }
                    if (deprecatedData.installData.source &&
                        deprecatedData.installData.source !== sync.source) {
                        sync.source = deprecatedData.installData.source;
                    }
                    if (!sync.hasPaid && deprecatedData.installData.paid) {
                        sync.hasPaid = true;
                    }
                    if (deprecatedData.installData.key &&
                        deprecatedData.installData.key !== sync.key) {
                        sync.key = deprecatedData.installData.key;
                    }
                }
                if (deprecatedData.tutorial !== null &&
                    deprecatedData.tutorial !== undefined &&
                    deprecatedData.tutorial === false) {
                    sync.timers.blocking_tutorial = DateTime.now().toMillis();
                    blockingTutorialSet = true;
                }
                if ((deprecatedData.showBATutorial !== null &&
                    deprecatedData.showBATutorial !== undefined &&
                    deprecatedData.showBATutorial === false) ||
                    (deprecatedData.showPinTutorial !== null &&
                        deprecatedData.showPinTutorial !== undefined &&
                        deprecatedData.showPinTutorial === false)) {
                    sync.timers.popup_tutorial = DateTime.now().toMillis();
                    popupTutorialSet = true;
                }
                if (deprecatedData.stats &&
                    deprecatedData.stats.totalAds &&
                    deprecatedData.stats.totalAds > 0) {
                    sync.stats.ads.total = deprecatedData.stats.totalAds;
                }
                if (deprecatedData.reviewAsked) {
                    sync.review_prompted = true;
                    reviewSet = true;
                }
                if (deprecatedData.paddleData) {
                    sync.paddle = deprecatedData.paddleData;
                }
                if (deprecatedData.fullPageLastShown) {
                    sync.timers.full_page = parseInt(deprecatedData.fullPageLastShown);
                }
                if (deprecatedData.notificationLastShown) {
                    sync.timers.notification = parseInt(deprecatedData.notificationLastShown);
                }
                if (deprecatedData.bannerLastShown) {
                    sync.timers.banner = parseInt(deprecatedData.bannerLastShown);
                }
                if (deprecatedData.allowAdsonSite && deprecatedData.allowAdsonSite.length) {
                    for (let i = 0; i < deprecatedData.allowAdsonSite.length; i++) {
                        const site = deprecatedData.allowAdsonSite[i];
                        if (site) {
                            const url = new URL(site);
                            if (url && !sync.whitelist.urls.includes(url.hostname)) {
                                sync.whitelist.urls.push(url.hostname);
                            }
                        }
                    }
                }
                log("ab_mv2Update", sync.source, sync.user_id, sync.uc.toString(), `hasPaid:${sync.hasPaid.toString()}-key:${sync.key}-btSet:${blockingTutorialSet}-ptSet:${popupTutorialSet}-rSet:${reviewSet}`);
            }
            catch (error) {
                console.error(error);
            }
        }
        const configData = await getConfig();
        sync.schedule = await getSchedule(configData.schedule);
        sync.timers.config = DateTime.now().toMillis();
        await setSessionRules(configData.rules, configData.whitelist);
        await saveSync(sync);
        await setSyncPaddleData(sync.paddle);
    }
    catch (error) {
        console.error(error);
    }
}
export async function handleOnInstalled(details) {
    if (details.reason === "install") {
        await init(true);
        log("ab_install", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString());
    }
    else if (details.reason === "update") {
        await init(false);
        log("ab_update", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString());
    }
}
