import { DateTime } from "luxon";
import { addToWhitelist, getConfig, getSync, saveSync, log, removeFromWhitelist, setCookie, setPopupIconStatus, setPopupForTrial, updateSiteBlockingEnabled, updateContextMenus, } from "..";
import { setSyncPaddleData } from "../paddle";
import { PaddleStates } from "../sync";
export const handleMessages = async (request, _sender, sendResponse) => {
    try {
        let sync = await getSync();
        if (sync !== undefined) {
            const subscription_id = sync.paddle.subscription_id || "";
            switch (request.type) {
                case "updateSiteBlockingStatus":
                    try {
                        const [tab] = await chrome.tabs.query({
                            active: true,
                            lastFocusedWindow: true,
                        });
                        const siteBlockingEnabled = await updateSiteBlockingEnabled(tab.url);
                        sendResponse(siteBlockingEnabled);
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                // disables blocking for the site
                case "addToWhitelist":
                    try {
                        const [tab] = await chrome.tabs.query({
                            active: true,
                            lastFocusedWindow: true,
                        });
                        addToWhitelist([tab.url]);
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                // enables blocking for the site
                case "removeFromWhitelist":
                    try {
                        const [tab] = await chrome.tabs.query({
                            active: true,
                            lastFocusedWindow: true,
                        });
                        const configData = await getConfig();
                        removeFromWhitelist([tab.url], configData.rules);
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "setAssetsForBlockingStatus":
                    sync = await getSync();
                    setPopupForTrial(sync.trialDay, sync.hasPaid);
                    setPopupIconStatus(sync.blockingEnabled && sync.siteBlockingEnabled);
                    break;
                case "getMatchedRules":
                    try {
                        sync = await getSync();
                        const hostname = request.hostname || "";
                        if (!sync.whitelist.urls.includes(hostname)) {
                            if (!sync.whitelist.urls.includes(hostname)) {
                                const [tab] = await chrome.tabs.query({
                                    active: true,
                                    lastFocusedWindow: true,
                                });
                                const details = await chrome.declarativeNetRequest.getMatchedRules({
                                    tabId: tab.id,
                                });
                                sync.stats.ads.session =
                                    details.rulesMatchedInfo.length;
                                sync.stats.ads.total +=
                                    details.rulesMatchedInfo.length;
                                sync.stats.data += 32;
                                sync.stats.time += 3;
                                await saveSync(sync);
                                sendResponse(details.rulesMatchedInfo.length);
                            }
                        }
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "popupOpened":
                    try {
                        sync = await getSync();
                        if (request.showTutorial) {
                            sync.timers.popup_tutorial =
                                DateTime.now().toMillis();
                            await saveSync(sync);
                            await chrome.tabs.create({
                                url: "https://adgone.org/adblocker/installsuccessful?uid=" +
                                    sync.user_id +
                                    "&uc=" +
                                    sync.uc +
                                    "&source=" +
                                    sync.source +
                                    "&activation=" +
                                    sync.hasPaid +
                                    "&implementation_id=adgone_" +
                                    chrome.runtime.getManifest().version +
                                    "&trialDay=" +
                                    sync.trialDay,
                                active: true,
                                selected: true,
                            });
                        }
                        sendResponse({
                            success: await log("ab_baction", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString()),
                        });
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "bannerClicked":
                    try {
                        sync = await getSync();
                        await chrome.tabs.create({
                            windowId: null,
                            index: null,
                            url: "https://adgone.org/adblocker/upgrade?uid=" +
                                sync.user_id +
                                "&uc=" +
                                sync.uc.toString() +
                                "&source=" +
                                sync.source +
                                "&sid=" +
                                subscription_id +
                                "&activation=" +
                                sync.hasPaid.toString() +
                                "&implementation_id=adgone_" +
                                chrome.runtime.getManifest().version +
                                "&trialDay=" +
                                sync.trialDay +
                                "&pageType=" +
                                request.pageType,
                            active: true,
                            selected: true,
                            pinned: null,
                            openerTabId: null,
                        });
                        sync.timers.banner = DateTime.now().toMillis();
                        await saveSync(sync);
                        sendResponse({
                            success: await log("ab_bannerClicked", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString()),
                        });
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "bannerClosed":
                    try {
                        sync = await getSync();
                        sync.timers.banner = DateTime.now().toMillis();
                        await saveSync(sync);
                        sendResponse({
                            success: await log("ab_bannerClosed", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), request.pageType),
                        });
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "pastDueBannerClicked":
                    try {
                        sync = await getSync();
                        await chrome.tabs.create({
                            windowId: null,
                            index: null,
                            url: "https://adgone.org/adblocker/upgrade?uid=" +
                                sync.user_id +
                                "&uc=" +
                                sync.uc.toString() +
                                "&source=" +
                                sync.source +
                                "&sid=" +
                                subscription_id +
                                "&activation=" +
                                sync.hasPaid.toString() +
                                "&implementation_id=adgone_" +
                                chrome.runtime.getManifest().version +
                                "&trialDay=" +
                                sync.trialDay +
                                "&pageType=" +
                                request.pageType,
                            active: true,
                            selected: true,
                            pinned: null,
                            openerTabId: null,
                        });
                        sync.timers.banner = DateTime.now().toMillis();
                        await saveSync(sync);
                        sendResponse({
                            success: await log("ab_pastDueBannerClicked", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), request.pageType),
                        });
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "pastDueBannerClosed":
                    try {
                        sync = await getSync();
                        sync.timers.banner = DateTime.now().toMillis();
                        await saveSync(sync);
                        sendResponse({
                            success: await log("ab_pastDueBannerClosed", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), request.pageType),
                        });
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "sendLog":
                    try {
                        sync = await getSync();
                        if (request.logName && request.logValue) {
                            const success = await log(request.logName, sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), request.logValue ? request.logValue : "");
                            sendResponse({ success });
                        }
                        else {
                            sendResponse({ success: false });
                        }
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "blockingTutorialClosed":
                    try {
                        sync = await getSync();
                        sync.timers.blocking_tutorial =
                            DateTime.now().toMillis();
                        await saveSync(sync);
                        await chrome.tabs.create({
                            url: "https://adgone.org/adblocker/tutorial?notify=true&uid=" +
                                sync.user_id +
                                "&uc=" +
                                sync.uc.toString() +
                                "&source=" +
                                sync.source +
                                "&sid=" +
                                subscription_id +
                                "&activation=" +
                                sync.hasPaid.toString() +
                                "&implementation_id=adgone_" +
                                chrome.runtime.getManifest().version +
                                "&trialDay=" +
                                sync.trialDay +
                                "&pageType=tutorialWidget",
                            active: true,
                            selected: true,
                        });
                        sendResponse({
                            success: await log("ab_blockingTutorialClosed", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), request.pageType),
                        });
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "popupTutorialShown":
                    try {
                        sync = await getSync();
                        sendResponse({
                            success: await log("ab_popupTutorialShown", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), request.pageType),
                        });
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "popupTutorialClosed":
                    try {
                        sync = await getSync();
                        sync.timers.popup_tutorial = DateTime.now().toMillis();
                        await saveSync(sync);
                        sendResponse({
                            success: await log("ab_popupTutorialClosed", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), request.pageType),
                        });
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "keyEntered":
                    console.log("messageHandler - keyEntered");
                    try {
                        sync = await getSync();
                        const url = "https://api.adgone.org/api/Validate?key=" +
                            request.key +
                            "&uc=" +
                            sync.uc.toString() +
                            "&user_id=" +
                            sync.user_id;
                        const response = await fetch(url);
                        const data = await response.text();
                        console.log("messageHandler - keyEntered - data", data);
                        if (data === "true") {
                            sync.key = request.key;
                            sync.hasPaid = true;
                            if (sync.paddle) {
                                sync.paddle.state = PaddleStates.active;
                                sync.paddle.subscription_id = undefined;
                                sync.paddle.last_updated = undefined;
                                setSyncPaddleData(sync.paddle).catch((error) => console.error(error));
                            }
                            await saveSync(sync);
                            await setCookie("AG_Subscriber", "true");
                            sendResponse({ paid: sync.hasPaid });
                        }
                        else if (data === "false") {
                            sync.hasPaid = false;
                            await saveSync(sync);
                            sendResponse({ paid: sync.hasPaid });
                        }
                        await log("ab_key_entered", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString());
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "activate":
                    try {
                        sync = await getSync();
                        sync.hasPaid = true;
                        sync.paddle.state = PaddleStates.active;
                        await saveSync(sync);
                        await log("ab_activated", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), sync.paddle.state);
                        setTimeout(() => setSyncPaddleData(sync.paddle).catch((error) => console.error(error)), 5000);
                        sendResponse({ paid: sync.hasPaid });
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "startEmailActivation":
                    try {
                        sync = await getSync();
                        if (request.updateUser) {
                            const url = `https://api.adgone.org/api/updateuser?old_user_id=${request.oldUserId}&new_user_id=${sync.user_id}&uc=${sync.uc.toString()}&source=${sync.source}`;
                            const response = await fetch(url);
                            const data = await response.json();
                            if (!data.success) {
                                await log("ab_emailActivationError", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), data.msg);
                                console.error(new Error(data.msg));
                                console.warn(data);
                            }
                            sync.paddle.state = PaddleStates.active;
                            await chrome.browserAction.setPopup({
                                popup: "html/popup.html",
                            });
                            setCookie("AG_Subscriber", "true");
                        }
                        sync.hasPaid = true;
                        if (request.email &&
                            request.email !== "" &&
                            (sync.paddle.user_email === undefined ||
                                sync.paddle.user_email === "")) {
                            sync.paddle.user_email = request.email;
                        }
                        sync.paddle.last_updated = undefined;
                        await saveSync(sync);
                        setTimeout(async () => {
                            try {
                                await setSyncPaddleData(sync.paddle);
                                if (sync.paddle.state === PaddleStates.past_due) {
                                    const tabs = await chrome.tabs.query({});
                                    tabs.forEach(async (tab) => {
                                        if (tab.url.includes("/adblocker/emailactivation")) {
                                            const qs = tab.url.split("?")[1];
                                            await chrome.tabs.update(tab.id, {
                                                active: true,
                                                url: "https://adgone.org/adblocker/updatepayment?" +
                                                    qs,
                                            });
                                        }
                                    });
                                }
                                else if (sync.paddle.state ===
                                    PaddleStates.deleted ||
                                    sync.paddle.state === PaddleStates.cancelled) {
                                    const tabs = await chrome.tabs.query({});
                                    tabs.forEach(async (tab) => {
                                        if (tab.url.includes("/adblocker/emailactivation")) {
                                            const qs = tab.url.split("?")[1];
                                            await chrome.tabs.update(tab.id, {
                                                active: true,
                                                url: "https://adgone.org/adblocker/upgrade?" +
                                                    qs,
                                            });
                                        }
                                    });
                                }
                            }
                            catch (error) {
                                console.error(error);
                            }
                        }, 5000);
                        await log("ab_emailActivation", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), sync.paddle.state);
                        sendResponse({ paid: sync.hasPaid });
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "userPaymentUpdated":
                    try {
                        sync = await getSync();
                        sync.hasPaid = true;
                        sync.paddle.state = PaddleStates.active;
                        sync.paddle.last_updated = undefined;
                        await saveSync(sync);
                        await log("ab_userPaymentUpdated", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), sync.paddle.state);
                        setTimeout(() => setSyncPaddleData(sync.paddle).catch((error) => console.error(error)), 5000);
                        await chrome.browserAction.setPopup({
                            popup: "html/popup.html",
                        });
                        sendResponse({ paid: sync.hasPaid });
                    }
                    catch (error) {
                        console.error(error);
                    }
                    return true;
                case "setContextMenus":
                    try {
                        sync = await getSync();
                        updateContextMenus(sync.siteBlockingEnabled);
                    }
                    catch (error) {
                        console.error(error);
                    }
                    break;
                case "csAdBlocked":
                    try {
                        sync = await getSync();
                        sync.stats.ads.session += 1;
                        sync.stats.ads.total += 1;
                        sync.stats.time += 100;
                        sync.stats.data += 32;
                        await saveSync(sync);
                    }
                    catch (error) {
                        console.error(error);
                    }
                    break;
                default:
                    sendResponse({
                        success: false,
                        message: "No message type provided",
                    });
            }
        }
    }
    catch (error) {
        console.error("errorHandler", error);
    }
};
