"use strict";
import { handleMessages } from "./lib/handlers/messageHandler";
import { handleOnInstalled } from "./lib/handlers/onInstalledHandler";
import { showFullPage } from "./lib/widgets/fullPage";
import { handleAlarms } from "./lib/handlers/alarmHandler";
import { addToWhitelist, getConfig, getTrialDay, removeFromWhitelist, setCookie, setSessionRules, getSync, createUrl, reloadCurrentTab, updateSiteBlockingEnabled, setPopupIconStatus, trialBlockingEnabled, updateContextMenus, saveSync, disableAllBlocking, setPopupForTrial, getSchedule, } from "./lib";
import { setSyncPaddleData } from "./lib/paddle";
import { setPopup } from "./lib/popup";
// * On Installed
chrome.runtime.onInstalled.addListener(async (details) => await handleOnInstalled(details));
// * init
(async () => {
    try {
        let sync = await getSync();
        if (sync !== undefined) {
            // @ts-ignore -- chrome hasn't updated their typings yet
            const userSettings = await chrome.action.getUserSettings();
            userSettings.isOnToolbar = true;
            sync.isPinned = userSettings.isOnToolbar;
            sync.trialDay = await getTrialDay();
            sync.blockingEnabled = trialBlockingEnabled(sync);
            if (!sync.blockingEnabled) {
                await disableAllBlocking();
                setPopupIconStatus(false);
            }
            else {
                // Config
                const configData = await getConfig();
                sync.schedule = await getSchedule(configData.schedule);
                await setSessionRules(configData.rules, configData.whitelist);
            }
            await saveSync(sync);
            // Cookies
            await setCookie("userID", sync.user_id);
            await setCookie("source", sync.source);
            await setCookie("userClass", sync.uc.toString());
            const subscriberCookie = await chrome.cookies.get({
                url: "https://adgone.org",
                name: "AG_Subscriber",
            });
            if ((subscriberCookie && subscriberCookie.value === "true") ||
                sync.hasPaid) {
                await setCookie("AG_Subscriber", "true");
            }
            setPopupForTrial(sync.trialDay, sync.hasPaid);
            setPopupIconStatus(sync.blockingEnabled && sync.siteBlockingEnabled);
            if (sync.hasPaid) {
                await setSyncPaddleData(sync.paddle);
            }
            await setPopup(sync);
            await showFullPage("load");
        }
    }
    catch (error) {
        console.error(error);
    }
    // * Alarms
    chrome.alarms.create("abStats", {
        delayInMinutes: 5,
        periodInMinutes: 60,
    });
    chrome.alarms.create("notify", { delayInMinutes: 1, periodInMinutes: 5 });
    chrome.alarms.create("popFullPage", {
        delayInMinutes: 1,
        periodInMinutes: 1,
    });
    chrome.alarms.create("premiumStatus", {
        delayInMinutes: 1,
        periodInMinutes: 4,
    });
    chrome.alarms.create("updateConfig", { periodInMinutes: 1440 });
    chrome.alarms.create("updatePaddleData", { periodInMinutes: 1440 });
    chrome.alarms.onAlarm.addListener(async (alarm) => {
        handleAlarms(alarm.name);
    });
    // * Notifications
    chrome.notifications.onClicked.addListener(async (_event) => {
        try {
            const sync = await getSync();
            if (sync !== undefined) {
                await chrome.tabs.create({
                    url: createUrl("upgrade", "notify", sync),
                    active: true,
                    selected: true,
                });
            }
        }
        catch (error) {
            console.error(error);
        }
    });
    // * Right Click Menus
    chrome.contextMenus.onClicked.addListener(async (info, _tab) => {
        switch (info.menuItemId) {
            case "addToWhitelist":
                addToWhitelist([info.pageUrl]);
                break;
            case "removeFromWhitelist":
                try {
                    const configData = await getConfig();
                    removeFromWhitelist([info.pageUrl], configData.rules);
                }
                catch (error) {
                    console.error(error);
                }
                break;
        }
        reloadCurrentTab();
    });
    // tab switching
    chrome.tabs.onActivated.addListener(({ tabId }) => {
        chrome.tabs.get(tabId).then(async (tab) => {
            if (tab.url) {
                try {
                    const sync = await getSync();
                    const siteBlockingEnabled = await updateSiteBlockingEnabled(tab.url);
                    setPopupIconStatus(sync.blockingEnabled && siteBlockingEnabled);
                    updateContextMenus(sync.blockingEnabled && siteBlockingEnabled);
                }
                catch (err) {
                    console.error(err);
                }
            }
        });
    });
})();
// * Runtime Messages
chrome.runtime.onMessage.addListener(async (request, sender, sendResponse) => await handleMessages(request, sender, sendResponse));
