/**
 * Gets the current popup (unpaid, paid, past_due)
 * @returns Popup
 */
export async function getCurrentPopup() {
    try {
        const popup = await chrome.action.getPopup({});
        let current = "unpaid";
        if (popup.endsWith("popupPaid.html")) {
            current = "paid";
        }
        if (popup.endsWith("popupPastDue.html")) {
            current = "past_due";
        }
        return current;
    }
    catch (error) {
        console.error(error);
    }
}
/**
 * Sets the popup to unpaid (trial), paid, or past due
 * @param sync
 * @returns Popup Type
 */
export async function setPopup(sync) {
    try {
        let popup = await getCurrentPopup();
        const trialExpired = sync.trialDay > 7 && sync.trialDay < 21 && sync.trialDay > 28;
        const activePaddleUser = (sync.hasPaid && sync.paddle.state === PaddleStates.active) ||
            (sync.hasPaid && !sync.paddle.state);
        const inactivePaddleUser = sync.paddle.state &&
            (sync.paddle.state === PaddleStates.cancelled ||
                sync.paddle.state === PaddleStates.deleted);
        const pastDuePaddleUser = sync.paddle.state && sync.paddle.state === PaddleStates.past_due;
        if (!sync.hasPaid && trialExpired) {
        }
        else if (popup !== PopupTypes.unpaid &&
            sync.trialDay < 8 &&
            (!sync.hasPaid || (sync.hasPaid && inactivePaddleUser))) {
            chrome.action.setPopup({ popup: PopupPaths.unpaid });
            popup = PopupTypes.unpaid;
        }
        else if (popup !== PopupTypes.paid && activePaddleUser) {
            chrome.action.setPopup({ popup: PopupPaths.paid });
            popup = PopupTypes.paid;
        }
        else if (popup !== PopupTypes.past_due && pastDuePaddleUser) {
            chrome.action.setPopup({ popup: PopupPaths.past_due });
            popup = PopupTypes.past_due;
        }
        return popup;
    }
    catch (error) {
        console.error(error);
    }
}
/**
 * Configures the Popup for blocking enabled.
 * @param elements
 */
export async function setBlockingElementsEnabled(elements) {
    elements.toggles.site.slider.classList.remove("la-times");
    elements.toggles.site.slider.classList.add("la-check");
    elements.toggles.site.slider.title =
        "Click to Disable blocking for this site";
    elements.statusBar.style.backgroundColor = "white";
    elements.status.style.color = "#4BBAE7";
    elements.status.innerText = "ON";
    elements.toggles.site.input.checked = true;
}
/**
 * Configures the Popup for blocking disabled.
 * @param elements
 */
export function setBlockingElementsDiabled(elements) {
    elements.toggles.site.slider.classList.remove("la-check");
    elements.toggles.site.slider.classList.add("la-times");
    elements.toggles.site.slider.title =
        "Click to Enable blocking for this site";
    elements.stats.session.innerText = "0";
    elements.statusBar.style.backgroundColor = "white";
    elements.status.style.color = "#ff4848";
    elements.status.innerText = "OFF";
    elements.toggles.site.input.checked = false;
}
/**
 * Initializes the popups. Sets stats, domain, version number, etc.
 * @param popup
 * @param elements
 * @param sync
 */
export async function initPopup(popup, elements, sync) {
    const currentUrl = new URL(await getCurrentUrl());
    if (!sync.blockingEnabled || !sync.siteBlockingEnabled) {
        setBlockingElementsDiabled(elements);
    }
    // * Set stats
    if (elements.stats) {
        elements.stats.session.innerText = sync.stats.ads.session.toString();
        elements.stats.total.innerText = sync.stats.ads.total.toString();
        elements.stats.data.innerText = await getStatsData();
        elements.stats.time.innerText = await getStatsTime();
    }
    // * Set domain
    if (elements.domain)
        elements.domain.innerText = getDomainFromUrl(currentUrl);
    // * Set version
    if (elements.settings.version)
        elements.settings.version.innerText =
            chrome.runtime.getManifest().version;
    // * Event listeners
    if (elements.toggles.site.input && elements.toggles.site.slider) {
        elements.toggles.site.input.addEventListener("click", function () {
            if (elements.toggles.site.input.checked == true) {
                setBlockingElementsEnabled(elements);
                chrome.runtime.sendMessage({ type: "removeFromWhitelist" });
            }
            else {
                setBlockingElementsDiabled(elements);
                chrome.runtime.sendMessage({ type: "addToWhitelist" });
            }
        });
    }
    if (elements.settings.open) {
        elements.settings.open.addEventListener("click", () => toggleSettingsPanel(elements));
    }
    if (elements.settings.close) {
        elements.settings.close.addEventListener("click", () => toggleSettingsPanel(elements));
    }
    if (elements.settings.key.btn) {
        elements.settings.key.btn.addEventListener("click", () => toggleSettingsPanel(elements));
    }
    if (elements.activateLink) {
        elements.activateLink.addEventListener("click", () => toggleSettingsPanel(elements));
    }
    if (elements.toggles.global.input && elements.toggles.site.input) {
        elements.toggles.global.input.addEventListener("click", function () {
            if (elements.toggles.global.input.checked == true) {
                //unpauseAllBlocking(elements);
                if (elements.toggles.site.input.checked == false) {
                    //setBlockingElementsEnabled(elements);
                    //chrome.runtime.sendMessage({ type: 'addToWhitelist' });
                }
            }
            else {
                //pauseAllBlocking(elements);
                if (elements.toggles.site.input.checked == true) {
                    //setBlockingElementsDiabled(elements);
                    //chrome.runtime.sendMessage({ type: 'removeFromWhitelist' });
                }
            }
        });
    }
    if (elements.settings.key.input && elements.settings.key.btn) {
        elements.settings.key.input.addEventListener("input", () => {
            elements.settings.key.btn.children[0].classList.remove("la-times");
            elements.settings.key.btn.children[0].classList.add("la-check");
            inputLengthCheck(elements.settings.key.input.value.replace(/[^0-9a-z]/gi, ""), elements);
        });
        elements.settings.key.input.addEventListener("keypress", (e) => {
            if (e.key === "Enter") {
                if (this.value.replace(/[^0-9a-z]/gi, "") < 32) {
                    // TODO: Make button red
                    return;
                }
                activateLicense(this.value.replace(/[^0-9a-z]/gi, ""), elements);
            }
        });
    }
    // * Set links/buttons
    switch (popup) {
        case "unpaid":
            if (elements.logo.btn)
                elements.logo.btn.href = createUrl("upgrade", "balogo", sync);
            if (elements.stats.btn)
                elements.stats.btn.href = createUrl("upgrade", "bastats", sync);
            elements.upgradeBtn.href = createUrl("upgrade", "baupgrade", sync);
            break;
        case "paid":
            if (elements.logo.btn)
                elements.logo.btn.href = createUrl("account", "balogo", sync);
            if (elements.stats.btn)
                elements.stats.btn.href = createUrl("account", "bastats", sync);
            break;
        case "past_due":
            if (elements.logo.btn)
                elements.logo.btn.href = createUrl("updatepayment", "balogo", sync);
            if (elements.stats.btn)
                elements.stats.btn.href = createUrl("updatepayment", "bastats", sync);
            if (elements.upgradeBtn)
                elements.upgradeBtn.href = createUrl("updatepayment", "baupgrade", sync);
            break;
        default:
            if (elements.logo.btn)
                elements.logo.btn.href = createUrl("upgrade", "balogo", sync);
            if (elements.stats.btn)
                elements.stats.btn.href = createUrl("upgrade", "bastats", sync);
            if (elements.upgradeBtn)
                elements.upgradeBtn.href = createUrl("upgrade", "baupgrade", sync);
            break;
    }
    if (sync.timers.blocking_paused.isPaused) {
        //setBlockingElementsDiabled(elements);
    }
}
/**
 * Configures the popup based on the user's trial time
 * @param elements
 * @param sync
 */
export function setTrial(elements, sync) {
    const firstTrialActive = sync.trialDay < 8;
    const secondTrialActive = sync.trialDay >= 29 && sync.trialDay <= 35;
    if (!sync.hasPaid && firstTrialActive) {
        // * first trial
        setExpiration(7 - sync.trialDay, elements);
    }
    else if (!sync.hasPaid && secondTrialActive) {
        // * second trial
        setExpiration(35 - sync.trialDay, elements); // TODO: Confirm 36 as end of second trial
    }
    else if ((!firstTrialActive && !secondTrialActive) ||
        (!sync.hasPaid && !sync.paddle) ||
        (!sync.hasPaid &&
            sync.paddle &&
            sync.paddle.state &&
            sync.paddle.state !== PaddleStates.active)) {
        // * expired
        elements.expiration.style.paddingTop = "0.95em";
        elements.status.style.color = "#ff4848";
        elements.status.innerText = "OFF";
        elements.toggles.site.slider.title =
            "Click to Enable blocking for this site";
        elements.trialHeader.innerHTML = `<p>Your trial has <span style="color:#ff4848;">EXPIRED</span><p>`;
        elements.trialHeader.style.display = "block";
        elements.upgradeBtn.style.backgroundColor = "#ff4848";
        elements.toggles.site.slider.parentElement.parentElement.parentElement.innerHTML = `
			<a id="expiredToggle" href="${createUrl("upgrade", "baToggle", sync)}" target="_blank" style="display:flex;justify-content:center;align-items:center;"><img src="../img/off-button.jpg" alt="off button" width="75"></a>
		`;
    }
}
/**
 * Sets the remaining trial time in the Popup.
 * @param days
 * @param elements
 */
export function setExpiration(days, elements) {
    elements.trialHeader.style.display = "block";
    if (days == 0) {
        elements.trialTimer.innerText = `${days} day`;
    }
    else {
        elements.trialTimer.innerText = `${days} days`;
    }
}
/**
 * Shows and hides the settings panel within the Popup.
 * @param elements
 */
export function toggleSettingsPanel(elements) {
    elements.settings.panel.classList.toggle("hidden");
    elements.settings.open.classList.toggle("shown");
    elements.settings.close.classList.toggle("shown");
}
/**
 * Configures the Popup to disable blocking globally.
 * @param elements
 */
export function pauseAllBlocking(elements) {
    elements.toggles.global.input.checked = false;
    elements.toggles.global.slider.classList.remove("la-times");
    elements.toggles.global.slider.classList.add("la-check");
    chrome.runtime.sendMessage({ type: "pauseBlocking", pause: true });
}
/**
 * Configures the Popup to enable blocking globally.
 * @param elements
 */
export function unpauseAllBlocking(elements) {
    elements.toggles.global.input.checked = true;
    elements.toggles.global.slider.classList.add("la-times");
    elements.toggles.global.slider.classList.remove("la-check");
    chrome.runtime.sendMessage({ type: "pauseBlocking", pause: false });
    elements.status.classList.remove("paused");
}
/**
 * Activates a user's extension from a manually entered product key.
 * @param value
 * @param elements
 */
export async function activateLicense(value, elements) {
    try {
        const sync = await getSync();
        if (sync !== undefined) {
            value = value.replace(/[^0-9a-z]/gi, "");
            const paid = await activate(value);
            if (paid) {
                elements.activateLink.innerText = "";
                elements.activateLink.style.pointerEvents = "none";
                elements.stats.container.style.paddingTop = "1em";
                elements.stats.container.style.paddingBottom = "1em";
                elements.expiration.style.paddingTop = "0";
                elements.expiration.innerHTML = `<span style = 'color: #a8a8a8'><br><br><br>Subscription Active<br></span>`;
                elements.expiration.style.justifyContent = "center";
                elements.expiration.style.alignItems = "center";
                elements.logo.btn.style.pointerEvents = "none";
                elements.settings.key.input.setAttribute("disabled", "");
                elements.settings.key.btn.style.pointerEvents = "none";
                elements.settings.key.btn.classList.add("success");
                elements.settings.key.btn.style.backgroundColor = "white";
                elements.settings.key.btn.style.pointerEvents = "none";
            }
            else {
                elements.settings.key.btn.style.backgroundColor = "#ffb4b4";
                elements.settings.key.btn.style.pointerEvents = "none";
                elements.settings.key.btn.children[0].classList.remove("la-check");
                elements.settings.key.btn.children[0].classList.add("la-times");
            }
        }
    }
    catch (error) {
        console.error(error);
    }
}
/**
 * Checks the length of the manually entered key for validity.
 * @param value
 * @param elements
 */
export function inputLengthCheck(value, elements) {
    if (value.length === 32) {
        elements.settings.key.btn.style.opacity = "1";
        elements.settings.key.btn.style.backgroundColor = "#ddd";
        elements.settings.key.btn.style.pointerEvents = "all";
        elements.settings.key.btn.style.cursor = "pointer";
        activateLicense(elements.settings.key.input.value, elements);
        elements.settings.key.btn.addEventListener("click", () => {
            activateLicense(elements.settings.key.input.value, elements);
        });
    }
    else {
        elements.settings.key.btn.style.opacity = "0.5";
        elements.settings.key.btn.style.backgroundColor = "#efefef";
        elements.settings.key.btn.style.pointerEvents = "none";
    }
}
