import { DateTime } from "luxon";
import { getSync, log, saveSync } from "../..";
import { PaddleStates } from "../../sync";
async function isActiveSubscriber() {
    try {
        const sync = await getSync();
        if (sync.hasPaid &&
            (!sync.paddle ||
                !sync.paddle.state ||
                (sync.paddle &&
                    sync.paddle.state &&
                    sync.paddle.state === PaddleStates.active))) {
            return true;
        }
        return false;
    }
    catch (error) {
        console.error(error);
    }
}
export async function showFullPage(alarmType) {
    try {
        const sync = await getSync();
        if (sync !== undefined) {
            const isActive = await isActiveSubscriber();
            const fullPageDay = sync.schedule.full_page.includes(sync.trialDay);
            const oldTrialUser = sync.trialDay >= 54;
            if (!isActive && (fullPageDay || oldTrialUser)) {
                // return if less than 24 hours since last pop
                if (sync.timers.full_page &&
                    DateTime.now().toMillis() - sync.timers.full_page < 86400000) {
                    return;
                }
                chrome.idle.queryState(15, async (stateType) => {
                    if (stateType !== "active" ||
                        alarmType === "load" ||
                        sync.trialDay === 8 ||
                        sync.trialDay === 29 ||
                        sync.trialDay === 36) {
                        const tabs = await chrome.tabs.query({});
                        tabs.forEach((tab) => {
                            if (tab.url.indexOf("adgone.org/adblocker/upgrade") > -1) {
                                chrome.tabs.remove(tab.id);
                            }
                        });
                        const subscription_id = sync.paddle.subscription_id
                            ? sync.paddle.subscription_id
                            : "";
                        let baseUrl = "https://adgone.org/adblocker/upgrade";
                        if (sync.paddle &&
                            sync.paddle.state === PaddleStates.past_due) {
                            baseUrl =
                                "https://adgone.org/adblocker/updatepayment";
                        }
                        chrome.tabs.create({
                            windowId: null,
                            index: null,
                            url: baseUrl +
                                "?uid=" +
                                sync.user_id +
                                "&uc=" +
                                sync.uc +
                                "&source=" +
                                sync.source +
                                "&sid=" +
                                subscription_id +
                                "&activation=" +
                                sync.hasPaid +
                                "&implementation_id=adgone_" +
                                chrome.runtime.getManifest().version +
                                "&trialDay=" +
                                sync.trialDay +
                                "&pageType=fullPage",
                            active: true,
                            selected: true,
                            pinned: null,
                            openerTabId: null,
                        });
                        sync.timers.full_page = DateTime.now().toMillis();
                        await saveSync(sync);
                        log("ab_upSellShown", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), "widgetFullPage");
                    }
                    else {
                        log("ab_tryShow", sync.source, sync.user_id, sync.uc.toString(), sync.hasPaid.toString(), stateType);
                    }
                });
            }
        }
    }
    catch (error) {
        console.error(error);
    }
}
